import assert from 'node:assert/strict';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';
import { resolve, dirname, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import micromatch from 'micromatch';
import { inherit, type Check } from '../../../src/check/check.ts';
import { parseCheckTreeAuthoring } from '../../../src/project-definition/check-tree/authoring.ts';
import { resolveCheckTree } from '../../../src/project-definition/check-tree/resolution.ts';
import { createCollectionFilesystem } from '../../../src/package-checks/project-files/filesystem-collection.ts';
import { CONFIG_GLOB_OPTIONS, selectConfigPaths } from '../../../src/data-boundary/config-glob.ts';
const root=process.cwd(); const out=resolve('tmp/optimization-implementation-20261015/definition');
function before(path:string,name:string) {
  const source=execFileSync('git',['show',`HEAD:${path}`],{encoding:'utf8'});
  const rewritten=source.replace(/(from\s+["'])(\.[^"']+)(["'])/gu,(_,a,s,b)=>a+pathToFileURL(resolve(dirname(resolve(path)),s)).href+b);
  fs.writeFileSync(join(out,name),rewritten);
  return import(pathToFileURL(join(out,name)).href);
}
const oldAuthoring=await before('src/project-definition/check-tree/authoring.ts','before-authoring.ts');
const oldResolution=await before('src/project-definition/check-tree/resolution.ts','before-resolution.ts');
const oldFilesystem=await before('src/package-checks/project-files/filesystem-collection.ts','before-filesystem.ts');
const execute=()=>({status:'passed' as const,data:{}});
const dag=[];
for(const depth of [3,5,7,9]) {
 const measure=(parse:typeof parseCheckTreeAuthoring)=>{let visits=0;const count=(c:Check)=>new Proxy(c,{ownKeys(t){visits++;return Reflect.ownKeys(t);}});let c:Check=count({checkId:'leaf',displayName:'Leaf',execute});for(let i=0;i<depth;i++)c=count({checkId:`g${i}`,displayName:'Group',checks:[c,c]});const parsed=parse([c]);return{visits,accepted:parsed!==undefined};};
 const before=measure(oldAuthoring.parseCheckTreeAuthoring),after=measure(parseCheckTreeAuthoring);
 assert.equal(before.visits,2**(depth+1)-1);assert.equal(after.visits,depth+2);assert.equal(after.accepted,false);dag.push({depth,before,after});
}
const inheritance=[];
for(const size of [16,32,64,128]){
 let c:Check={checkId:'leaf',displayName:'Leaf',execute};for(let i=0;i<size;i++)c={checkId:`g${i}`,displayName:'Group',mutex:inherit({add:[`cost-mutex-${i}`]}),checks:[c]};
 const measure=(resolveTree:typeof resolveCheckTree)=>{const sort=Array.prototype.sort,filter=Array.prototype.filter;let sortedElements=0,filteredElements=0;Reflect.set(Array.prototype,'sort',function(this:unknown[],compare:unknown){if(typeof this[0]==='string'&&this[0].startsWith('cost-mutex-'))sortedElements+=this.length;return Reflect.apply(sort,this,[compare]);});Reflect.set(Array.prototype,'filter',function(this:unknown[],cb:unknown,arg:unknown){if(typeof this[0]==='string'&&this[0].startsWith('cost-mutex-'))filteredElements+=this.length;return Reflect.apply(filter,this,[cb,arg]);});try{const tree=resolveTree([c],1);assert.equal(tree?.leaves[0]?.mutex.length,size);return{sortedElements,filteredElements};}finally{Reflect.set(Array.prototype,'sort',sort);Reflect.set(Array.prototype,'filter',filter);}};
 const before=measure(oldResolution.resolveCheckTree),after=measure(resolveCheckTree);assert.equal(before.filteredElements,size*(size-1)/2);assert.equal(before.sortedElements,size*(size+1)/2);assert.equal(after.filteredElements,0);assert.equal(after.sortedElements,size);inheritance.push({size,before,after});
}
const literal=[];
for(const size of [16,64,128]){
 const paths=Array.from({length:size},(_,i)=>`cost-file-${i}.ts`),patterns=[...paths].reverse();
 const measure=(select:typeof selectConfigPaths)=>{const exec=RegExp.prototype.exec;let nativeLiteralTests=0;Reflect.set(RegExp.prototype,'exec',function(this:RegExp,input:string){if(this.source.includes('cost\\-file\\-'))nativeLiteralTests++;return Reflect.apply(exec,this,[input]);});try{assert.deepEqual(select(paths,patterns),patterns);return{nativeLiteralTests};}finally{Reflect.set(RegExp.prototype,'exec',exec);}};
 const before=measure((p,q)=>micromatch([...p],[...q],CONFIG_GLOB_OPTIONS)),after=measure(selectConfigPaths);assert.equal(before.nativeLiteralTests,size*(size-1));assert.equal(after.nativeLiteralTests,0);literal.push({size,before,after});
}
const prefix=[];
for(const depth of [8,16,24]){
 const fixture=join(out,`prefix-fixture-${depth}`),target=join(fixture,'prefix-cost',...Array.from({length:depth},(_,i)=>`d${i}`));fs.mkdirSync(target,{recursive:true});
 const measure=(create:typeof createCollectionFilesystem)=>{const slice=Array.prototype.slice;let copiedPrefixSlots=0;Reflect.set(Array.prototype,'slice',function(this:unknown[],start:number,end:number){if(this[0]==='prefix-cost')copiedPrefixSlots+=(end??this.length)-(start??0);return Reflect.apply(slice,this,[start,end]);});try{create(fixture,[{patterns:['**/*','!**/absent/**'],useDefaultExcludes:false}]).readdirSync!(target,{withFileTypes:true});return{copiedPrefixSlots};}finally{Reflect.set(Array.prototype,'slice',slice);}};
 const before=measure(oldFilesystem.createCollectionFilesystem),after=measure(createCollectionFilesystem);assert.ok(before.copiedPrefixSlots>0);assert.equal(after.copiedPrefixSlots,0);prefix.push({depth,before,after});
}
const evidence={capturedAt:new Date().toISOString(),head:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),runtime:process.versions,method:'Actual before source copied from HEAD with only import locations rewritten, compared to current implementations. Current common imported value parsers remain equivalent on these legal inheritance/filesystem fixtures. No timing or heap claims.',dag,inheritance,literal,prefix};fs.writeFileSync(join(out,'operation-counts.json'),JSON.stringify(evidence,null,2)+'\n');console.log(JSON.stringify(evidence,null,2));
